/**
 * Netscape cookie-file formatting.
 *
 * Kept free of Electron imports (the `Cookie` import is type-only) so the format
 * is unit-tested under plain Node.
 */

import type { Cookie } from 'electron';

function safeField(value: string): string {
  return value.replace(/[\t\r\n]/gu, '');
}

/** Netscape cookie-file text for yt-dlp's `--cookies`. */
export function toNetscape(cookies: readonly Cookie[]): string {
  const lines = [
    '# Netscape HTTP Cookie File',
    '# Generated by Hypagon Gateway for one yt-dlp run. Do not keep this file.',
    '',
  ];

  for (const cookie of cookies) {
    const domain = safeField(cookie.domain ?? '');
    if (domain === '' || cookie.name === '') continue;
    const expiry = typeof cookie.expirationDate === 'number' ? Math.floor(cookie.expirationDate) : 0;
    const includeSubdomains = cookie.hostOnly ? 'FALSE' : 'TRUE';
    const secure = cookie.secure ? 'TRUE' : 'FALSE';
    const cookiePath = safeField(cookie.path || '/');
    lines.push(
      [
        domain,
        includeSubdomains,
        cookiePath,
        secure,
        String(expiry),
        safeField(cookie.name),
        safeField(cookie.value ?? ''),
      ].join('\t'),
    );
  }

  return `${lines.join('\n')}\n`;
}
